package uk.ac.ravensbourne.casevault.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.core.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import uk.ac.ravensbourne.casevault.repository.UserAccountRepository;
/** Rejects an existing server-side session as soon as its account becomes disabled (CWE-613). */
@Component public class DisabledAccountSessionFilter extends OncePerRequestFilter { private final UserAccountRepository users; public DisabledAccountSessionFilter(UserAccountRepository u){users=u;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {var a=SecurityContextHolder.getContext().getAuthentication();if(a!=null&&a.getPrincipal() instanceof UserPrincipal p&&!users.findById(p.id()).map(u->u.isEnabled()).orElse(false)){var session=r.getSession(false);if(session!=null)session.invalidate();SecurityContextHolder.clearContext();s.sendRedirect("/login?expired");return;}c.doFilter(r,s);} }
